-- Backend completion, additive to the reconciled C-002 foundation. No seed data.
begin;

-- Bind cursors to the authenticated actor, complete filter, and current version.
create or replace function private.rad_page_position(body jsonb,version text) returns jsonb
language plpgsql set search_path='' as $$
declare p private.rad_page_tokens; wanted_hash text:=md5((body-'cursor')::text);
begin
 if body->>'cursor' is null then return null; end if;
 if body->>'cursor' !~ '^[0-9a-f-]{36}$' then raise exception 'cursor_expired' using errcode='PT409'; end if;
 select * into p from private.rad_page_tokens where token=(body->>'cursor')::uuid;
 if not found or p.expires_at<=now() or p.actor<>coalesce(auth.uid()::text,'public')
 or p.filter_hash<>wanted_hash or p.version<>version then raise exception 'cursor_expired' using errcode='PT409'; end if;
 return p.position;
end $$;

-- API-only interaction storage. Pending comments require a human moderator;
-- approving a comment does not publish/revise the parent Feed item.
create table public.rad_feed_comments(
 id uuid primary key default gen_random_uuid(),feed_id uuid not null references public.feed_items(id),
 user_id uuid not null references auth.users(id),parent_id uuid references public.rad_feed_comments(id),
 body text not null check(char_length(btrim(body)) between 1 and 4000 or (state='deleted' and body='')),
 state text not null default 'pending' check(state in ('pending','visible','hidden','deleted')),
 revision integer not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index rad_comments_feed_idx on public.rad_feed_comments(feed_id,created_at,id);
create index rad_comments_owner_idx on public.rad_feed_comments(user_id,created_at desc);
create index rad_comments_parent_idx on public.rad_feed_comments(parent_id);
create table private.rad_comment_events(
 id bigint generated always as identity primary key,comment_id uuid not null references public.rad_feed_comments(id),
 actor_id uuid not null references auth.users(id),revision integer not null,state text not null,note text not null default '',created_at timestamptz not null default now()
);
create index rad_comment_events_comment_idx on private.rad_comment_events(comment_id,id);
create trigger rad_comment_events_immutable before update or delete on private.rad_comment_events for each row execute function private.rad_immutable();
alter table public.rad_feed_comments enable row level security;
alter table private.rad_comment_events enable row level security;
revoke all on public.rad_feed_comments,private.rad_comment_events from public,anon,authenticated,service_role;
create function private.rad_comment_json(c public.rad_feed_comments) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('id',c.id,'feed_id',c.feed_id,'parent_id',c.parent_id,'body',case when c.state='deleted' then '' else c.body end,
 'state',c.state,'revision',c.revision,'is_owner',c.user_id=auth.uid(),
 'created_at',to_char(c.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
$$;
create function private.rad_comment_mutate(operation text,p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=private.rad_require_owner();prior jsonb;c public.rad_feed_comments;parent public.rad_feed_comments;
begin
 if operation='moderate_feed_comment' then perform private.rad_require_admin(); end if;
 prior:=private.rad_begin_mutation(operation,p_request);if prior is not null then return prior;end if;
 if operation='create_feed_comment' then
  perform pg_advisory_xact_lock(hashtextextended('comment:'||actor::text,0));
  if not exists(select 1 from public.feed_items where id=(p_request->>'feed_id')::uuid and status='published' and published_at<=now() and (expires_at is null or expires_at>now())) then raise exception 'not_found' using errcode='PT404';end if;
  if (select count(*) from public.rad_feed_comments where user_id=actor and created_at>now()-interval '1 hour')>=30 then raise exception 'comment_rate_limited' using errcode='PT429';end if;
  if p_request->>'parent_id' is not null then
   select * into parent from public.rad_feed_comments where id=(p_request->>'parent_id')::uuid and feed_id=(p_request->>'feed_id')::uuid and state='visible' for share;
   if not found then raise exception 'parent_not_found' using errcode='PT404';end if;
   -- Bound recursion independently from UI/product nesting preferences.
   if (with recursive ancestors as(select id,parent_id,1 depth from public.rad_feed_comments where id=parent.id union all select ancestor_comment.id,ancestor_comment.parent_id,a.depth+1 from public.rad_feed_comments ancestor_comment join ancestors a on ancestor_comment.id=a.parent_id where a.depth<8) select max(depth) from ancestors)>=8 then raise exception 'thread_depth_limit' using errcode='PT422';end if;
  end if;
  insert into public.rad_feed_comments(feed_id,user_id,parent_id,body) values((p_request->>'feed_id')::uuid,actor,(p_request->>'parent_id')::uuid,btrim(p_request->>'body')) returning * into c;
 else
  select * into c from public.rad_feed_comments where id=(p_request->>'comment_id')::uuid and (user_id=actor or operation='moderate_feed_comment') for update;
  if not found then raise exception 'not_found' using errcode='PT404';end if;
  if c.revision<>(p_request->>'expected_revision')::integer or c.state='deleted' then raise exception 'revision_conflict' using errcode='PT409';end if;
  if operation='delete_feed_comment' then
   -- Only the author can delete; moderator removal preserves the original audit.
   if c.user_id<>actor then raise exception 'not_found' using errcode='PT404';end if;
   update public.rad_feed_comments set state='deleted',body='',revision=revision+1,updated_at=now() where id=c.id returning * into c;
  else
   if nullif(btrim(p_request->>'note'),'') is null then raise exception 'moderation_note_required' using errcode='PT422';end if;
   update public.rad_feed_comments set state=p_request->>'state',revision=revision+1,updated_at=now() where id=c.id returning * into c;
  end if;
 end if;
 insert into private.rad_comment_events(comment_id,actor_id,revision,state,note) values(c.id,actor,c.revision,c.state,coalesce(p_request->>'note',''));
 return private.rad_finish_mutation(operation,p_request,private.rad_envelope(private.rad_comment_json(c)));
end $$;
create function public.create_feed_comment(p_request jsonb) returns jsonb language sql security definer set search_path='' as $$select private.rad_comment_mutate('create_feed_comment',p_request)$$;
create function public.delete_feed_comment(p_request jsonb) returns jsonb language sql security definer set search_path='' as $$select private.rad_comment_mutate('delete_feed_comment',p_request)$$;
create function public.moderate_feed_comment(p_request jsonb) returns jsonb language sql security definer set search_path='' as $$select private.rad_comment_mutate('moderate_feed_comment',p_request)$$;
create function public.list_feed_comments(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb;version text;off integer;lim integer:=(p_request->>'limit')::integer;total integer;
begin
 perform private.rad_assert_request('list_feed_comments',p_request);
 if not exists(select 1 from public.feed_items where id=(p_request->>'feed_id')::uuid and status='published' and published_at<=now() and (expires_at is null or expires_at>now())) then raise exception 'not_found' using errcode='PT404';end if;
 select md5(coalesce(string_agg(id::text||revision::text,',' order by id),'')) into version from public.rad_feed_comments where feed_id=(p_request->>'feed_id')::uuid;
 off:=coalesce((private.rad_page_position(p_request,version)->>'offset')::integer,0);
 with visible as(select * from public.rad_feed_comments c where feed_id=(p_request->>'feed_id')::uuid and (state='visible' or user_id=auth.uid() or private.has_role(array['admin','super_admin']))),
 page as(select * from visible order by created_at,id offset off limit lim)
 select (select count(*) from visible),coalesce(jsonb_agg(private.rad_comment_json(p) order by created_at,id),'[]') into total,result from page p;
 return private.rad_envelope(jsonb_build_object('items',result),null,private.rad_page(p_request,version,jsonb_build_object('offset',off+lim),total>off+lim));
end $$;
revoke all on function public.create_feed_comment(jsonb),public.delete_feed_comment(jsonb),public.moderate_feed_comment(jsonb) from public,anon,service_role;
grant execute on function public.create_feed_comment(jsonb),public.delete_feed_comment(jsonb),public.moderate_feed_comment(jsonb) to authenticated;
revoke all on function public.list_feed_comments(jsonb) from public,service_role;
grant execute on function public.list_feed_comments(jsonb) to anon,authenticated;

-- Resume pointers are owner-only and always resolved against published content.
create table public.rad_visa_reading_state(
 user_id uuid not null references auth.users(id),article_id uuid not null references public.visa_articles(id),locale text not null check(locale in ('fa','en')),
 section_id uuid,saved boolean not null,revision integer not null default 1,updated_at timestamptz not null default now(),primary key(user_id,article_id,locale)
);
alter table public.rad_visa_reading_state enable row level security;
revoke all on public.rad_visa_reading_state from public,anon,authenticated,service_role;
create index rad_visa_reading_article_idx on public.rad_visa_reading_state(article_id);
create function public.save_visa_reading_state(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=private.rad_require_owner();prior jsonb;s public.rad_visa_reading_state;published uuid;expected integer;
begin
 prior:=private.rad_begin_mutation('save_visa_reading_state',p_request);if prior is not null then return prior;end if;
 perform pg_advisory_xact_lock(hashtextextended('reading:'||actor::text||(p_request->>'article_id')||(p_request->>'locale'),0));
 select published_id into published from public.visa_article_heads where article_id=(p_request->>'article_id')::uuid and locale=p_request->>'locale';
 if published is null then raise exception 'not_found' using errcode='PT404';end if;
 if p_request->>'section_id' is not null and not exists(select 1 from public.visa_article_sections where revision_id=published and id=(p_request->>'section_id')::uuid) then raise exception 'section_not_found' using errcode='PT404';end if;
 select * into s from public.rad_visa_reading_state where user_id=actor and article_id=(p_request->>'article_id')::uuid and locale=p_request->>'locale';
 expected:=case when found then s.revision else 0 end;
 if expected<>(p_request->>'expected_revision')::integer then raise exception 'revision_conflict' using errcode='PT409';end if;
 insert into public.rad_visa_reading_state(user_id,article_id,locale,section_id,saved,revision) values(actor,(p_request->>'article_id')::uuid,p_request->>'locale',(p_request->>'section_id')::uuid,(p_request->>'saved')::boolean,expected+1)
 on conflict(user_id,article_id,locale) do update set section_id=excluded.section_id,saved=excluded.saved,revision=excluded.revision,updated_at=now() returning * into s;
 return private.rad_finish_mutation('save_visa_reading_state',p_request,private.rad_envelope(jsonb_build_object('article_id',s.article_id,'locale',s.locale,'section_id',s.section_id,'saved',s.saved,'revision',s.revision)));
end $$;
create function public.get_visa_reading_state(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=private.rad_require_owner();s public.rad_visa_reading_state;published uuid;
begin
 perform private.rad_assert_request('get_visa_reading_state',p_request);
 select published_id into published from public.visa_article_heads where article_id=(p_request->>'article_id')::uuid and locale=p_request->>'locale';
 if published is null then raise exception 'not_found' using errcode='PT404';end if;
 select * into s from public.rad_visa_reading_state where user_id=actor and article_id=(p_request->>'article_id')::uuid and locale=p_request->>'locale';
 return private.rad_envelope(jsonb_build_object('article_id',p_request->'article_id','locale',p_request->'locale','saved',coalesce(s.saved,false),'revision',coalesce(s.revision,0),
 'section_id',case when exists(select 1 from public.visa_article_sections where revision_id=published and id=s.section_id) then s.section_id else null end));
end $$;
revoke all on function public.save_visa_reading_state(jsonb),public.get_visa_reading_state(jsonb) from public,anon,service_role;
grant execute on function public.save_visa_reading_state(jsonb),public.get_visa_reading_state(jsonb) to authenticated;

-- Content-hash change detection persists review candidates only. Requires an
-- existing protected-fetch authority proof and an unexpired worker lease.
create function public.record_official_source_change(p_job_id uuid,p_lease_token uuid,p_article_id uuid,p_locale text,p_old_snapshot_id uuid,p_new_snapshot_id uuid,p_new_sections jsonb,p_changes jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare j private.rad_research_jobs;old_source public.source_snapshots;new_source public.source_snapshots;
 doc public.source_documents;authority uuid;r public.visa_article_revisions;proposal public.visa_research_proposals;change jsonb;existing jsonb;computed jsonb;
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'forbidden' using errcode='PT403';end if;
 select * into j from private.rad_research_jobs where id=p_job_id and lease_token=p_lease_token and lease_until>now() and status='running' and kind='research_refresh' for share;
 if not found then raise exception 'lease_invalid' using errcode='PT409';end if;
 if p_locale is null or p_locale not in ('fa','en') or p_new_sections is null or jsonb_typeof(p_new_sections)<>'array' or jsonb_array_length(p_new_sections) not between 1 and 100
 or p_changes is null or jsonb_typeof(p_changes)<>'array' or jsonb_array_length(p_changes) not between 1 and 100 then raise exception 'invalid_change' using errcode='PT422';end if;
 select * into old_source from public.source_snapshots where id=p_old_snapshot_id;
 select * into new_source from public.source_snapshots where id=p_new_snapshot_id;
 if old_source.id is null or new_source.id is null or old_source.document_id<>new_source.document_id then raise exception 'snapshot_mismatch' using errcode='PT422';end if;
 if old_source.content_hash=new_source.content_hash then return jsonb_build_object('changed',false,'proposal_id',null);end if;
 if new_source.http_status is distinct from 200 or new_source.fetched_at>now() or new_source.content_hash<>encode(extensions.digest(new_source.normalized_text,'sha256'),'hex') then raise exception 'snapshot_invalid' using errcode='PT422';end if;
 if new_source.fetched_at<=old_source.fetched_at then raise exception 'snapshot_order' using errcode='PT422';end if;
 select * into doc from public.source_documents where id=new_source.document_id and removed_at is null and validation_status='validated' and source_authority<>'rad_official';
 select a.id into authority from private.authority_entities a join private.authority_domains d on d.authority_id=a.id
 join private.authority_proofs proof on proof.domain_id=d.id join private.authority_trust_roots root on root.id=proof.root_id
 where left(doc.canonical_url,length('https://'||d.host||d.path_prefix))='https://'||d.host||d.path_prefix and a.state='verified' and d.state='verified'
 and a.expires_at>now() and d.expires_at>now() and proof.expires_at>now() and proof.revoked_at is null and proof.domain_revision=d.revision
 and root.active and root.expires_at>now() and (j.request->'authority_ids') ? a.id::text order by a.id limit 1;
 if authority is null then raise exception 'official_evidence_required' using errcode='PT422';end if;
 select rev.* into r from public.visa_article_heads h join public.visa_article_revisions rev on rev.id=h.head_id where h.article_id=p_article_id and h.locale=p_locale;
 if not found then raise exception 'not_found' using errcode='PT404';end if;
 computed:=r.body->'sections';
 if exists(select 1 from jsonb_array_elements(p_changes) c group by c->>'section_id' having count(*)>1) then raise exception 'duplicate_change' using errcode='PT422';end if;
 for change in select * from jsonb_array_elements(p_changes) loop
  if not private.rad_schema_valid((select schema from private.rad_contract_schemas where name='SectionChange'),change) then raise exception 'invalid_change' using errcode='PT422';end if;
  select section into existing from jsonb_array_elements(computed) section where section->>'id'=change->>'section_id';
  if change->>'operation'='add' then
   if existing is not null or change->>'before_hash' is not null then raise exception 'change_conflict' using errcode='PT409';end if;
  elsif existing is null or change->>'before_hash' is distinct from encode(extensions.digest(existing::text,'sha256'),'hex') then raise exception 'change_conflict' using errcode='PT409';end if;
  if change->>'operation'='remove' then
   if change->'replacement'<>'null'::jsonb then raise exception 'invalid_change' using errcode='PT422';end if;
  elsif change->'replacement'->>'id' is distinct from change->>'section_id' or not exists(
    select 1 from jsonb_array_elements(change->'replacement'->'evidence_refs') e where e->>'snapshot_id'=p_new_snapshot_id::text and length(e->>'excerpt')>0 and position(e->>'excerpt' in new_source.normalized_text)>0) then
   raise exception 'change_evidence_required' using errcode='PT422';
  end if;
  select coalesce(jsonb_agg(section),'[]') into computed from jsonb_array_elements(computed) section where section->>'id'<>change->>'section_id';
  if change->>'operation'<>'remove' then computed:=computed||jsonb_build_array(change->'replacement');end if;
 end loop;
 select jsonb_agg(section order by (section->>'order')::integer) into computed from jsonb_array_elements(computed) section;
 if computed is distinct from p_new_sections then raise exception 'undeclared_section_change' using errcode='PT422';end if;
 -- Validate the full draft schema without saving, approving, or publishing it.
 perform private.rad_assert_request('save_visa_article_draft',r.body||jsonb_build_object('sections',p_new_sections,'expected_revision',r.revision,'request_key',gen_random_uuid()));
 insert into public.visa_research_proposals(article_id,locale,base_revision,authority_id,old_snapshot_id,new_snapshot_id,changes,new_sections)
 values(p_article_id,p_locale,r.revision,authority,p_old_snapshot_id,p_new_snapshot_id,p_changes,p_new_sections)
 on conflict(article_id,locale,base_revision,new_snapshot_id) do nothing returning * into proposal;
 if proposal.id is null then select * into proposal from public.visa_research_proposals where article_id=p_article_id and locale=p_locale and base_revision=r.revision and new_snapshot_id=p_new_snapshot_id;end if;
 return jsonb_build_object('changed',true,'proposal_id',proposal.id);
end $$;
revoke all on function public.record_official_source_change(uuid,uuid,uuid,text,uuid,uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.record_official_source_change(uuid,uuid,uuid,text,uuid,uuid,jsonb,jsonb) to service_role;

-- Currency alert replay and consent corrections.
create or replace function private.rad_alert_mutate(operation text,body jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare owner uuid:=private.rad_require_owner(); prior jsonb; a public.currency_alerts; result jsonb;
begin
 prior:=private.rad_begin_mutation(operation,body);if prior is not null then return prior; end if;
 perform pg_advisory_xact_lock(hashtextextended('currency-alert:'||owner::text,0));
 if operation='create_currency_alert' then
  if (select count(*) from public.currency_alerts where user_id=owner and enabled and deleted_at is null)>=50 then raise exception 'alert_limit' using errcode='PT422'; end if;
  insert into public.currency_alerts(user_id,base,quote,direction,threshold,cooldown_seconds)
  values(owner,body->>'base',body->>'quote',body->>'direction',(body->>'threshold')::numeric,(body->>'cooldown_seconds')::integer) returning * into a;
 else
  select * into a from public.currency_alerts where id=(body->>'alert_id')::uuid and user_id=owner and deleted_at is null for update;
  if not found then raise exception 'not_found' using errcode='PT404'; end if;
  if a.revision<>(body->>'expected_revision')::integer then raise exception 'revision_conflict' using errcode='PT409'; end if;
  if operation='delete_currency_alert' then
   update public.currency_alerts set enabled=false,deleted_at=now(),revision=revision+1 where id=a.id;
   result:=private.rad_envelope(private.rad_ack());
  else
   if not a.enabled and (body->>'enabled')::boolean and (select count(*) from public.currency_alerts where user_id=owner and enabled and deleted_at is null)>=50 then raise exception 'alert_limit' using errcode='PT422';end if;
   update public.currency_alerts set threshold=(body->>'threshold')::numeric,direction=a.direction,enabled=(body->>'enabled')::boolean,
    cooldown_seconds=(body->>'cooldown_seconds')::integer,revision=revision+1,last_side=null where id=a.id returning * into a;
  end if;
 end if;
 if result is null then result:=private.rad_envelope(private.rad_alert_json(a)); end if;
 return private.rad_finish_mutation(operation,body,result);
end $$;
create or replace function public.record_fx_observation(p_observation jsonb) returns uuid language plpgsql security definer set search_path='' as $$
declare o public.fx_observations; a public.currency_alerts; side boolean; notification uuid;
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'forbidden' using errcode='PT403'; end if;
 if p_observation is null or jsonb_typeof(p_observation)<>'object' or not (p_observation ?& array['provider','base','quote','rate','observation_date','source_url']) or exists(select 1 from jsonb_each(p_observation) e where e.value='null'::jsonb) then raise exception 'invalid_observation' using errcode='PT422';end if;
 if p_observation->>'base'='IRT' or p_observation->>'quote'='IRT' then raise exception 'toman_is_display_only' using errcode='PT422';end if;
 if (p_observation->>'provider'='frankfurter' and p_observation->>'source_url' !~ '^https://api[.]frankfurter[.]dev/v2/rate/[a-z]{3}/[a-z]{3}$')
 or (p_observation->>'provider'='fawazahmed0' and p_observation->>'source_url' !~ '^https://(cdn[.]jsdelivr[.]net/npm/@fawazahmed0/currency-api@latest|latest[.]currency-api[.]pages[.]dev)/v1/currencies/[a-z]{3}[.]min[.]json$')
 or (p_observation->>'observation_date')::date>current_date or (p_observation->>'observation_date')::date<current_date-7
 or p_observation->>'rate' !~ '^(0|[1-9][0-9]*)([.][0-9]{1,18})?$' then raise exception 'invalid_observation' using errcode='PT422'; end if;
 insert into public.fx_observations(provider,base,quote,rate,observation_date,source_url)
 values(p_observation->>'provider',p_observation->>'base',p_observation->>'quote',(p_observation->>'rate')::numeric,(p_observation->>'observation_date')::date,p_observation->>'source_url')
 on conflict(provider,base,quote,observation_date,rate_basis) do nothing returning * into o;
 if o.id is null then select * into o from public.fx_observations where provider=p_observation->>'provider' and base=p_observation->>'base' and quote=p_observation->>'quote' and observation_date=(p_observation->>'observation_date')::date;return o.id;end if;
 -- Only fresh observations advance threshold state. Lock each alert exactly once.
 if o.observation_date<current_date then return o.id; end if;
 for a in select * from public.currency_alerts where enabled and deleted_at is null and base=o.base and quote=o.quote order by id for update loop
  if a.last_observation_id is not null and exists(select 1 from public.fx_observations where id=a.last_observation_id and observation_date>=o.observation_date) then continue; end if;
  side:=case a.direction when 'above' then o.rate>=a.threshold else o.rate<=a.threshold end;
  if side and a.last_side=false and coalesce((select currency_alerts from public.notification_preferences where user_id=a.user_id),true) and (a.last_triggered_at is null or a.last_triggered_at+make_interval(secs=>a.cooldown_seconds)<=now()) then
   insert into private.currency_alert_events(alert_id,observation_id) values(a.id,o.id) on conflict do nothing;
   if found then
    insert into public.notifications(user_id,type,title,body,action_path,source_id,target)
    values(a.user_id,'system','Currency reference alert',a.base||'/'||a.quote||' provider_reference: '||o.rate::text,'/profile/currency-alerts/'||a.id,a.id,jsonb_build_object('kind','currency_alert','id',a.id,'section_id',null)) returning id into notification;
    update private.currency_alert_events set notification_id=notification where alert_id=a.id and observation_id=o.id;
    update public.currency_alerts set last_triggered_at=now() where id=a.id;
   end if;
  end if;
  update public.currency_alerts set last_side=side,last_observation_id=o.id where id=a.id;
 end loop;
 return o.id;
end $$;
create trigger rad_snapshot_immutable before update or delete on public.source_snapshots for each row execute function private.rad_immutable();
create or replace function private.rad_claim_eligible(claim uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(
  select 1 from private.claim_official_evidence e
  join public.knowledge_claims k on k.id=e.claim_id
  join public.knowledge_citations c on c.id=e.citation_id and c.claim_id=k.id
  join public.source_snapshots s on s.id=c.snapshot_id
  join public.source_documents doc on doc.id=s.document_id
  join private.authority_proofs p on p.id=e.proof_id
  join private.authority_domains d on d.id=p.domain_id
  join private.authority_entities a on a.id=d.authority_id
  join private.authority_trust_roots r on r.id=p.root_id
  where e.claim_id=claim and k.is_current and not e.conflicting
   and p.revoked_at is null and p.domain_revision=d.revision
   and p.expires_at>now() and e.fresh_until>now() and d.expires_at>now() and a.expires_at>now()
   and e.verified_at<=now() and p.verified_at<=now() and s.fetched_at<=now() and s.http_status=200
   and s.content_hash=encode(extensions.digest(s.normalized_text,'sha256'),'hex')
   and r.active and r.expires_at>now() and d.state='verified' and a.state='verified'
   and doc.validation_status='validated' and doc.source_authority<>'rad_official'
   and e.topic=p.scope_topic and e.topic=any(a.competence_topics)
   and e.jurisdiction=p.jurisdiction and e.jurisdiction=a.jurisdiction
   and (p.profession='*' or p.profession=e.profession)
   and e.effective_from<=current_date and (e.effective_until is null or e.effective_until>=current_date)
   and left(doc.canonical_url,length('https://'||d.host||d.path_prefix))='https://'||d.host||d.path_prefix
   and doc.removed_at is null and k.claim_text=c.excerpt
   and length(c.excerpt)>0 and position(c.excerpt in s.normalized_text)>0 and nullif(c.locator,'') is not null
 ) and not exists(select 1 from private.claim_official_evidence where claim_id=claim and conflicting);
$$;
create or replace function public.approve_visa_source_inventory(p_request jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=private.rad_require_admin();prior jsonb;ids uuid[];id uuid;rev integer;hash text;publisher text;publishers text[]:='{}';
begin
 prior:=private.rad_begin_mutation('approve_visa_source_inventory',p_request);if prior is not null then return prior; end if;
 perform pg_advisory_xact_lock(hashtextextended('visa-inventory:'||(p_request->>'article_id'),0));
 select coalesce(max(revision),0) into rev from private.visa_source_inventories where article_id=(p_request->>'article_id')::uuid;
 if rev<>(p_request->>'expected_inventory_revision')::integer then raise exception 'inventory_conflict' using errcode='PT409'; end if;
 ids:=array(select distinct value::uuid from jsonb_array_elements_text(p_request->'source_snapshot_ids') value order by value::uuid);
 if exists(select 1 from public.source_snapshots inventory_snapshot where inventory_snapshot.id=any(ids) group by inventory_snapshot.document_id having count(*)>1) then raise exception 'multiple_source_versions' using errcode='PT422';end if;
 if cardinality(ids)<2 then raise exception 'both_publishers_required' using errcode='PT422'; end if;
 foreach id in array ids loop
  publisher:=private.rad_classify_snapshot(id);publishers:=publishers||publisher;
  perform private.rad_check_ancestry(array[id]);
 end loop;
 if not ('radvisa'=any(publishers) and 'digivisa'=any(publishers)) then raise exception 'both_publishers_required' using errcode='PT422'; end if;
 select encode(extensions.digest(string_agg(s.id::text||':'||s.content_hash,',' order by s.id),'sha256'),'hex') into hash from public.source_snapshots s where s.id=any(ids);
 insert into private.visa_source_inventories(article_id,revision,snapshot_ids,inventory_hash,approved_by) values((p_request->>'article_id')::uuid,rev+1,ids,hash,actor);
 return private.rad_finish_mutation('approve_visa_source_inventory',p_request,private.rad_envelope(jsonb_build_object('inventory_revision',rev+1,'inventory_hash',hash,'source_snapshot_ids',to_jsonb(ids))));
end $$;
-- Evidence displayed for one quote cannot borrow a different quote's proof.
create or replace function private.rad_evidence(ref jsonb,section uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('source_document_id',d.id,'snapshot_id',s.id,'claim_id',ref->'claim_id','section_id',section,
 'url',d.canonical_url,'publisher',coalesce(proof.name,d.title),'source_class',case when proof.id is not null then 'official_primary' else coalesce(o.publisher,'other') end,
 'authority_id',proof.id,'excerpt',ref->>'excerpt','locator',ref->'locator',
 'fetched_at',to_char(s.fetched_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
 'verified_at',to_char(proof.verified_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
 'fresh_until',to_char(proof.fresh_until at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
 'verification_state',case when proof.id is not null then 'verified' else 'unverified' end,'freshness_state',case when proof.id is not null then 'fresh' else 'unknown' end)
 from public.source_snapshots s join public.source_documents d on d.id=s.document_id
 left join private.visa_source_origins o on o.snapshot_id=s.id
 left join lateral(select a.id,a.name,e.verified_at,least(e.fresh_until,p.expires_at,domain.expires_at,a.expires_at,root.expires_at) fresh_until
 from private.claim_official_evidence e join public.knowledge_citations c on c.id=e.citation_id
 join private.authority_proofs p on p.id=e.proof_id join private.authority_domains domain on domain.id=p.domain_id
 join private.authority_entities a on a.id=domain.authority_id join private.authority_trust_roots root on root.id=p.root_id
 where e.claim_id=(ref->>'claim_id')::uuid and c.snapshot_id=s.id and c.excerpt=ref->>'excerpt' and c.locator is not distinct from ref->>'locator'
 and private.rad_claim_eligible(e.claim_id) and not e.conflicting and e.fresh_until>now() and p.expires_at>now() and p.revoked_at is null
 and p.domain_revision=domain.revision and domain.state='verified' and domain.expires_at>now() and root.active and root.expires_at>now()
 and a.state='verified' and a.expires_at>now() order by e.fresh_until desc limit 1) proof on true
 where s.id=(ref->>'snapshot_id')::uuid;
$$;
create or replace function private.rad_proposal_json(p public.visa_research_proposals) returns jsonb language sql stable set search_path='' as $$
 select jsonb_build_object('id',p.id,'revision',p.revision,'target_article_id',p.article_id,'base_revision',p.base_revision,
 'old_snapshot_id',p.old_snapshot_id,'new_snapshot_id',p.new_snapshot_id,'authority_id',p.authority_id,'changes',p.changes,
 'evidence',(select coalesce(jsonb_agg(private.rad_evidence(e,(section->>'id')::uuid)),'[]') from jsonb_array_elements(p.new_sections) section cross join lateral jsonb_array_elements(section->'evidence_refs') e),
 'verification_state','unverified','editorial_state',p.state,
 'created_at',to_char(p.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
 'reviewed_at',case when p.reviewed_at is null then null else to_char(p.reviewed_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') end,'reviewed_by',p.reviewed_by);
$$;
create or replace function public.reserve_rad_ai_request(p_user_id uuid,p_request_key uuid,p_body_hash text,p_reserved_output_tokens integer,p_session_id uuid default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare prior private.rad_ai_invocations;quota jsonb;v_role text;budget integer;used bigint;reserved bigint;
 day timestamptz:=date_trunc('day',now() at time zone 'utc') at time zone 'utc';
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'forbidden' using errcode='PT403'; end if;
 if p_user_id is null or p_request_key is null or p_body_hash is null or p_reserved_output_tokens is null or p_body_hash !~ '^[0-9a-f]{64}$' or p_reserved_output_tokens not between 1 and 8192 then raise exception 'invalid_reservation' using errcode='PT422'; end if;
 if p_session_id is not null and not exists(select 1 from public.ai_sessions where id=p_session_id and user_id=p_user_id) then raise exception 'session_forbidden' using errcode='PT403'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_user_id::text||':'||day::text,0));
 select * into prior from private.rad_ai_invocations where actor=p_user_id::text and request_key=p_request_key;
 if found then
  if prior.body_hash<>p_body_hash then raise exception 'idempotency_conflict' using errcode='PT409'; end if;
  if prior.created_at<now()-interval '24 hours' then raise exception 'request_expired' using errcode='PT409'; end if;
  return jsonb_build_object('allowed',true,'request_id',prior.request_id,'replayed',true,'state',prior.state,'response',prior.response,'http_status',prior.http_status);
 end if;
 select p.role into v_role from public.profiles p where id=p_user_id;
 if not found then raise exception 'user_not_found' using errcode='PT403'; end if;
 select daily_output_tokens into budget from public.ai_usage_limits l where l.role=v_role;
 if budget is null then raise exception 'quota_unavailable' using errcode='PT503'; end if;
 select coalesce(sum(output_tokens),0) into used from public.ai_requests where user_id=p_user_id and created_at>=day;
 select coalesce(sum(reserved_output_tokens),0) into reserved from private.rad_ai_invocations where actor=p_user_id::text and state='running' and created_at>=day;
 if used+reserved+p_reserved_output_tokens>budget then return jsonb_build_object('allowed',false,'error','daily_token_limit_reached'); end if;
 quota:=private.rad_consume_ai_quota_base(p_user_id,v_role);
 if quota->>'allowed'<>'true' or quota->>'request_id' is null then return quota; end if;
 insert into private.rad_ai_invocations(actor,request_key,body_hash,request_id,reserved_output_tokens)
 values(p_user_id::text,p_request_key,p_body_hash,(quota->>'request_id')::uuid,p_reserved_output_tokens);
 update public.ai_requests set session_id=p_session_id where id=(quota->>'request_id')::uuid;
 return quota||jsonb_build_object('replayed',false,'state','running');
end $$;
create or replace function public.settle_rad_ai_request(p_request_id uuid,p_http_status integer,p_response jsonb,p_output_tokens integer)
returns boolean language plpgsql security definer set search_path='' as $$
declare invocation private.rad_ai_invocations;
begin
 if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'forbidden' using errcode='PT403'; end if;
 select * into invocation from private.rad_ai_invocations where request_id=p_request_id for update;
 if not found then raise exception 'reservation_required' using errcode='PT409'; end if;
 if invocation.state<>'running' then return false; end if;
 if p_output_tokens is null or p_http_status is null or p_response is null or jsonb_typeof(p_response)<>'object' or p_output_tokens not between 0 and invocation.reserved_output_tokens or p_http_status not between 200 and 599 or octet_length(p_response::text)>150000 then raise exception 'invalid_settlement' using errcode='PT422'; end if;
 update private.rad_ai_invocations set state=case when p_http_status=200 then 'succeeded' else 'failed' end,
 response=p_response,http_status=p_http_status,finished_at=now() where request_id=p_request_id;
 update public.ai_requests set status=case when p_http_status=200 then 'succeeded' else 'failed' end,output_tokens=p_output_tokens,
 safe_error_code=case when p_http_status=200 then null else 'copilot_failed' end,finished_at=now() where id=p_request_id;
 return true;
end $$;
